parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "title": {
      "type": "string",
      "description": "事件標題，只放事件名稱，例如『廠商會議』『客戶簡報』『教育訓練』，不要包含時間或地點文字"
    },
    "start_datetime": {
      "type": "string",
      "description": "開始時間，必須是帶 +08:00 時區偏移的 ISO 8601 字串，例如 2026-09-17T10:00:00+08:00"
    },
    "duration_minutes": {
      "type": "number",
      "description": "活動長度（分鐘）。使用者沒有說明時長時填 60"
    },
    "location": {
      "type": "string",
      "description": "地點。使用者沒有提到地點時填空字串，絕對不要自己編造"
    },
    "is_all_day": {
      "type": "boolean",
      "description": "是否為全天事件。使用者說『全天』『整天』『一整天』時為 true，否則為 false"
    }
  },
  "required": ["title", "start_datetime", "duration_minutes", "location", "is_all_day"]
}

parameters.jsCode:
// 把 Information Extractor 抽到的欄位補齊、驗證，並算出結束時間
const TZ = 'Asia/Taipei';
const out = [];

for (const item of $input.all()) {
  const d = item.json.output ?? item.json;

  const title = (d.title && String(d.title).trim()) || '未命名事件';
  const location = d.location ? String(d.location).trim() : '';   // 沒講地點 → 空字串，流程不會壞
  const isAllDay = d.is_all_day === true;
  const mins = Number(d.duration_minutes) > 0 ? Number(d.duration_minutes) : 60; // 預設值 60

  // 防呆一：模型沒抽到開始時間
  if (!d.start_datetime) {
    out.push({ json: { ok: false, reason: '我看不出你說的時間，可以再講一次嗎？例如「明天早上十點開會」', title } });
    continue;
  }

  // 防呆二：抽到的不是合法時間字串
  const start = DateTime.fromISO(String(d.start_datetime), { zone: TZ });
  if (!start.isValid) {
    out.push({ json: { ok: false, reason: `時間格式看不懂（${d.start_datetime}），可以換個講法嗎？`, title } });
    continue;
  }

  let startISO, endISO;
  if (isAllDay) {
    // 全天事件：當天 00:00 到隔天 00:00
    startISO = start.setZone(TZ).startOf('day').toISO();
    endISO = start.setZone(TZ).startOf('day').plus({ days: 1 }).toISO();
  } else {
    startISO = start.setZone(TZ).toISO();
    endISO = start.setZone(TZ).plus({ minutes: mins }).toISO();
  }

  out.push({
    json: {
      ok: true,
      title,
      location,
      is_all_day: isAllDay,
      duration_minutes: isAllDay ? 1440 : mins,
      start_datetime: startISO,
      end_datetime: endISO,
    },
  });
}

return out;

// 清洗：把 Google Calendar 回傳的事件整理成給人看的 LINE 訊息（覆述結果）
const TZ = 'Asia/Taipei';
const WD = ['日', '一', '二', '三', '四', '五', '六'];

const g = $json;                                   // Google Calendar 回傳的事件
const src = $('Code 算結束時間').first().json;      // 我們自己算好的乾淨欄位
const replyToken = $('LINE Webhook').first().json.body.events[0].replyToken;

const start = DateTime.fromISO(g.start?.dateTime || g.start?.date || src.start_datetime).setZone(TZ);
const end = DateTime.fromISO(g.end?.dateTime || g.end?.date || src.end_datetime).setZone(TZ);

let timeText;
if (src.is_all_day) {
  timeText = `${start.toFormat('M/d')}(${WD[start.weekday % 7]}) 全天`;
} else {
  timeText = `${start.toFormat('M/d')}(${WD[start.weekday % 7]}) ${start.toFormat('HH:mm')} - ${end.toFormat('HH:mm')}`;
}

const lines = [
  '✅ 已幫您排入行事曆',
  '',
  `📌 ${g.summary || src.title}`,
  `🕒 ${timeText}`,
];
if (src.location) lines.push(`📍 ${src.location}`);   // 沒地點就不顯示這行
lines.push('', '有錯的話再講一次就好～');

return [{ json: { replyToken, messages: [{ type: 'text', text: lines.join('\n') }] } }];

// 擷取失敗時的回覆，一樣走同一個 HTTP Request 節點
const replyToken = $('LINE Webhook').first().json.body.events[0].replyToken;
const reason = $json.reason || '我沒聽懂，可以再說一次嗎？';

return [{
  json: {
    replyToken,
    messages: [{ type: 'text', text: `⚠️ ${reason}` }],
  },
}];
